import{_ as l,l as o,o as e,c as n,v as t,p as s,x as i,d as E,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"LER 对器件的影响","description":"","frontmatter":{"title":"LER 对器件的影响","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/ler-device-impact.md","filePath":"litho/ler-device-impact.md","lastUpdated":1789023840000}'),p={name:"litho/ler-device-impact.md"};function c(m,a,_,f,D,L){const r=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="ler-对器件的影响" tabindex="-1">LER 对器件的影响 <a class="header-anchor" href="#ler-对器件的影响" aria-label="Permalink to &quot;LER 对器件的影响&quot;">​</a></h1><div class="epigraph"><p>计量 LER 是边怎么毛；器件问的是沟道宽、漏电路径和击穿间距怎么被这张谱抽样。频率权重与 SEM 协议不必相同。</p><footer>—— 据 LER 对 FinFET / 平面 MOSFET 电学影响的公开讨论；谱权重见计量与器件文献通称</footer></div><p><a href="/litho/ler-correlation-length">上一课</a>把 \\(\\xi\\) 与低频钉住。缺口是电学：同样积分 LER，高频毛刺与长程蜿蜒对阈值电压、关态漏电、栅氧/间距击穿的权重不同。本课钉 LER 对器件的影响。印刷失效（桥与断）是更极端的几何，留给<a href="/litho/bridge-break-defects">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>平面 MOS：沟道宽度沿 \\(W\\) 被两边 LER 调制，有效 \\(W\\) 涨落进 \\(I_\\mathrm{on}/I_\\mathrm{off}\\)；短沟再叠局部势垒。FinFET / GAA：鳍宽直接是线 CD，LWR 变成 \\(V_t\\) 与寄生电阻的局部散；相关长度相对鳍长，决定许多鳍是共模还是独立抽样。击穿与漏电更吃最小间距：低频蜿蜒让两线在某一点贴近，比密毛刺更危险。</p><p>缺口不是再报 PSD 怎么测，而是：器件传递函数是另一道滤波。ITRS 计量窗不一定等于沟道长度。用计量 \\(3\\sigma\\) 当电学规格的充分统计，会漏掉 \\(\\xi\\) 与最小间距尾。</p><h3 id="平均-cd-合格可以电学失败" tabindex="-1">平均 CD 合格可以电学失败 <a class="header-anchor" href="#平均-cd-合格可以电学失败" aria-label="Permalink to &quot;平均 CD 合格可以电学失败&quot;">​</a></h3><p>OPC 把均值鳍宽放进规格。局部最窄处决定漏电或开路风险。这与<a href="/litho/euv-stochastics">随机效应</a> 的「均值 OPC 修不掉尾」同构，对象从孔换成线宽调制。DTCO 要把 LER 谱而不是一个纳米数送进 SPICE 抽样。</p><p><span class="marginnote">刻蚀后鳍的 LER 才是器件几何。ADI 谱要经过转移函数；有的高频被修圆，有的被侧壁粗糙放大。声明 AEI。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>映射：把边实现（实验或 MC）做成器件网格，抽 \\(V_t\\)、\\(I_\\mathrm{off}\\)、击穿。简化：用 \\(\\xi\\) 与幅度生成相关随机边界。比较：只压高频（加核）看漏电是否真降——若最小间距由低频主导，加核几乎不帮，还伤分辨率。设计规则：线宽/间距余量要按谱的低频功率加，而不是按计量 LER 的一半。</p><p>与 LCDU：多鳍并联时，鳍间 CD 散是 LCDU 语言，鳍内沿长度是 LER。两者进不同的失配项。</p>',12)),(e(),s(h,null,{default:i(()=>[d(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PSD%5B%22LER%20%E8%B0%B1%22%5D%20--%3E%20W%5B%22%E5%B1%80%E9%83%A8%E7%BA%BF%E5%AE%BD%20%2F%20%E9%B3%8D%E5%AE%BD%22%5D%0A%20%20W%20--%3E%20VT%5B%22Vt%20%2F%20Ion%22%5D%0A%20%20LF%5B%22%E4%BD%8E%E9%A2%91%E8%9C%BF%E8%9C%92%22%5D%20--%3E%20GAP%5B%22%E6%9C%80%E5%B0%8F%E9%97%B4%E8%B7%9D%22%5D%0A%20%20GAP%20--%3E%20LEAK%5B%22%E6%BC%8F%E7%94%B5%20%2F%20%E5%87%BB%E7%A9%BF%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>电导对最窄截面敏感（非线性），\\(I_\\mathrm{off}\\) 对势垒更指数。于是边分布的尾比均方根更重要——又一次极值。\\(\\xi\\) 长，一条鳍内部相关，等效于整鳍偏置，像局部 CDU；\\(\\xi\\) 短，沿沟道平均，部分噪声被沟道长度滤掉，但密毛刺增加表面散射。节点缩小时沟道更短，滤波变弱，同一 \\(\\xi\\) 更疼。</p><p>High-NA 更细的鳍让相对 LWR 变大。光学 NILS 若跟着变好，幅度可降；电子核不跟着 NA 降，材料地板在。这是随机预算进器件，不是再写瑞利公式。</p><p><span class="marginnote">接触孔电阻吃 LCDU 与缺孔，不吃线 LER。层别对象不能混。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把某代 FinFET 的 mV/\\(V_t\\) 数写成课标。不发明器件论文 arXiv。下一课桥与断是几何连通性失败，比 \\(V_t\\) 散更靠良率墙；本课默认线还连着、孔还开着。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>器件对 LER 的滤波不同于 SEM 协议；必须用谱和 \\(\\xi\\)，不是单 \\(3\\sigma\\)。</li><li>低频蜿蜒伤最小间距与击穿；高频伤表面与短沟平均。</li><li>均值 CD 进规格不等于电学尾合格。</li><li>声明 AEI 几何；鳍内 LER 与鳍间 LCDU 分列。</li><li>出处：LER–器件公开讨论；谱方法接上一课。</li></ul>',8))])}const u=l(p,[["render",c]]);export{B as __pageData,u as default};
